// Строки синхронизации SAT с прототипом (SAT-SYNC-PLAN B13) живут в своём файле — вливаем их в каждый язык
for (const l of Object.keys(SAT_SYNC_DICT)) Object.assign(dict[l], SAT_SYNC_DICT[l])

for (const [language, values] of Object.entries(LEGAL_AND_PRICING)) Object.assign(dict[language === 'kz' ? 'kk' : language], values)

const I18nCtx = createContext(null)

export function I18nProvider({ children }) {
  const [lang, setLangState] = useState(() => {
    try {
      const saved = localStorage.getItem('lang')
      if (saved && dict[saved]) return saved
    } catch (e) {
      /* ignore */
    }
    return 'ru'
  })

  const setLang = useCallback((l) => {
    setLangState(l)
    try {
      localStorage.setItem('lang', l)
    } catch (e) {
      /* ignore */
    }
  }, [])

  // Язык — атрибутом на <html>: по нему казахский интерфейс целиком идёт на
  // Inter (src/kk-font.css). До гидратации его ставит UI_LANG_BOOT в layout.
  useEffect(() => applyUiLang(lang), [lang])

  const t = useCallback(
    (key, vars) => {
      let s = (dict[lang] && dict[lang][key]) ?? dict.ru[key] ?? key
      if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k])
      return s
    },
    [lang],
  )

  return <I18nCtx.Provider value={{ lang, setLang, t }}>{children}</I18nCtx.Provider>
}

export function useI18n() {
  return useContext(I18nCtx)
}
